const API_URL='https://uuzctytbguqjumwpczfh.supabase.co/functions/v1/bodysmith-api';
const API_KEY='sb_publishable_ibEVVafS4THz-16p4euMfg_qjG2WeU2';
const TOKEN_KEY='bodysmith-token-v2';
let CACHE_KEY='bodysmith-cache-v2';
let QUEUE_KEY='bodysmith-queue-v2';
const app=document.querySelector('#app');
const toastEl=document.querySelector('#toast');

const S={screen:'workout',authMode:'login',token:localStorage.getItem(TOKEN_KEY)||'',user:null,plan:null,history:[],active:null,activeDay:null,activeIndex:0,detail:null,selectedDayId:null,rest:0,restTimer:null,busy:false,online:navigator.onLine,authError:'',search:'',swapOpen:false,exercises:[],plans:[],supplements:[],supplementLogs:[],checkins:[],editor:null,suppEditor:null,saveBusy:false};

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtTime=s=>`${Math.floor(Math.max(0,s)/60)}:${String(Math.max(0,s)%60).padStart(2,'0')}`;
const fmtDur=s=>{s=Math.max(0,Math.round(Number(s)||0));const m=Math.floor(s/60),sec=s%60;return m>=60?`${Math.floor(m/60)}h ${m%60}m`:`${m}:${String(sec).padStart(2,'0')}`};
const initials=n=>String(n||'BS').trim().split(/\s+/).slice(0,2).map(x=>x[0]?.toUpperCase()).join('')||'BS';
const cache=()=>{try{return JSON.parse(localStorage.getItem(CACHE_KEY)||'{}')}catch{return{}}};
const setCache=x=>localStorage.setItem(CACHE_KEY,JSON.stringify({...x,exercises:S.exercises,plans:S.plans,supplements:S.supplements,supplementLogs:S.supplementLogs,checkins:S.checkins}));
const getQueue=()=>{try{return JSON.parse(localStorage.getItem(QUEUE_KEY)||'[]')}catch{return[]}};
const setQueue=q=>localStorage.setItem(QUEUE_KEY,JSON.stringify(q));
function toast(msg,error=false){toastEl.textContent=msg;toastEl.className=`show${error?' error':''}`;clearTimeout(toastEl._t);toastEl._t=setTimeout(()=>toastEl.className='',2800)}

async function api(action,payload={},options={}){
  const controller=new AbortController();
  const t=setTimeout(()=>controller.abort(),options.timeout||15000);
  try{
    const res=await fetch(API_URL,{method:'POST',headers:{'Content-Type':'application/json','apikey':API_KEY},body:JSON.stringify({action,...payload,...(S.token?{token:S.token}:{})}),signal:controller.signal});
    const data=await res.json().catch(()=>({error:'Invalid server response'}));
    if(!res.ok) throw Object.assign(new Error(data.error||`Request failed (${res.status})`),{status:res.status,data});
    return data;
  }finally{clearTimeout(t)}
}

function days(){return (S.plan?.plan_days||[]).slice().sort((a,b)=>a.sort_order-b.sort_order)}
function dayExercises(day){return (day?.plan_day_exercises||[]).slice().sort((a,b)=>a.sort_order-b.sort_order).map(slot=>({...slot,exercise:slot.exercises||{}}))}
function allExercises(){const map=new Map();for(const d of days())for(const slot of dayExercises(d)){const e=slot.exercise;if(e?.id&&!map.has(e.id))map.set(e.id,{...e,slots:[slot]});else if(e?.id)map.get(e.id).slots.push(slot)}for(const e of S.exercises||[])if(!map.has(e.id))map.set(e.id,{...e,slots:[]});return [...map.values()].sort((a,b)=>a.name.localeCompare(b.name))}
function dayById(id){return days().find(d=>d.id===id)||null}
function slotByExercise(day,exerciseId){return dayExercises(day).find(x=>x.exercise.id===exerciseId)||null}
function latestCompleted(){return S.history.find(h=>h.status==='completed')||null}
function nextDay(){const ds=days();if(!ds.length)return null;const last=latestCompleted();if(!last)return ds[0];const idx=ds.findIndex(d=>d.id===last.plan_day_id);return ds[(idx+1+ds.length)%ds.length]||ds[0]}
function selectedDay(){return dayById(S.selectedDayId)||nextDay()||days()[0]||null}
function activeSets(){return S.active?.sets||[]}
function setsFor(exId){return activeSets().filter(x=>x.exercise_id===exId).sort((a,b)=>a.set_number-b.set_number)}
function previousSets(exId){for(const h of S.history){if(h.status!=='completed')continue;const xs=(h.sets||[]).filter(x=>x.exercise_id===exId&&x.completion_status==='completed').sort((a,b)=>a.set_number-b.set_number);if(xs.length)return xs.map(x=>({...x,weight:x.weight==null?null:Math.round(Number(x.weight)*((x.units||'lb')===S.user.units?1:S.user.units==='kg'?1/2.2046226218:2.2046226218)*100)/100}))}return[]}
function activeProgress(){if(!S.activeDay)return{logged:0,planned:0,pct:0};const slots=dayExercises(S.activeDay);const planned=slots.reduce((n,s)=>n+s.target_sets,0);const logged=activeSets().filter(x=>x.completion_status==='completed'||x.completion_status==='skipped').length;return{logged,planned,pct:planned?Math.round(logged/planned*100):0}}
function nextUnfinishedIndex(day){const slots=dayExercises(day);for(let i=0;i<slots.length;i++){const s=slotByExercise(day,slots[i].exercise.id);if(setsFor(s.exercise.id).length<s.target_sets)return i}return Math.max(0,slots.length-1)}
function rpeUpper(t){const nums=String(t||'').match(/[\d.]+/g)?.map(Number)||[];return nums.length?Math.max(...nums):10}
function workoutScore(session,day){const slots=dayExercises(day);const planned=slots.reduce((n,s)=>n+s.target_sets,0);const sets=(session?.sets||[]).filter(x=>x.completion_status==='completed');const completion=planned?Math.min(1,sets.length/planned):0;const avgRpe=sets.length?sets.reduce((n,x)=>n+(Number(x.rpe)||0),0)/sets.length:0;const rpeScore=avgRpe?Math.max(0,1-Math.abs(avgRpe-7.5)/4):.7;const maxPain=sets.reduce((m,x)=>Math.max(m,Number(x.elbow_pain)||0),0);const painScore=maxPain>=6?.25:maxPain>=4?.65:1;return Math.round((completion*.55+rpeScore*.25+painScore*.20)*100)}

const mediaSlugs=new Set(["dumbbell-bench-press", "incline-machine-press", "machine-shoulder-press", "cable-chest-fly", "cable-lateral-raise", "rope-triceps-pressdown", "treadmill-walk", "neutral-grip-lat-pulldown", "seated-cable-row", "chest-supported-row", "one-arm-cable-row", "rear-delt-fly", "cable-curl", "hammer-curl", "back-extension", "romanian-deadlift", "leg-press-or-squat", "seated-leg-curl", "leg-extension", "calf-raise", "walking-lunge-or-split-squat", "cable-crunch", "incline-dumbbell-press", "lateral-raise", "goblet-squat", "dumbbell-row", "push-up", "glute-bridge", "plank"]);
function mediaPath(e){const slug=e.slug==='neutral-grip-pulldown'?'neutral-grip-lat-pulldown':e.slug;return mediaSlugs.has(slug)?`./media/${slug}.webp`:null}
function art(e,large=false){const src=mediaPath(e);return `<div class="exercise-art${large?' large':''}">${src?`<img src="${src}" alt="${esc(e.name)} start position" loading="lazy">`:`<div class="empty">${esc(e.name)}<br>Custom movement</div>`}</div>`}
function movementDemo(e){const src=mediaPath(e);return src?`<div class="movement-demo"><div class="sprite" role="img" aria-label="${esc(e.name)}: start and finish positions" style="background-image:url('${src}')"></div></div><div class="row-actions"><button class="secondary" data-demo-pause>Pause</button><button class="secondary" data-demo-speed>Slow speed</button></div><p class="muted tiny">Two-position movement guide${e.slug==='leg-press-or-squat'?' · Leg press variation shown':e.slug==='walking-lunge-or-split-squat'?' · Split squat variation shown':e.slug==='plank'?' · Hold the position and breathe':''}. Read the setup cue below. Muscle highlights are illustrative.</p>`:`<section class="panel"><h2>Movement instructions</h2><p>${esc(e.cue||'Add your setup instructions to this custom exercise.')}</p><p class="muted">Custom exercise: no verified movement illustration.</p></section>`}

function cloudBadge(){return `<div class="cloud ${S.online?'':'offline'}"><i></i>${getQueue().length?`<button class="sync-button" data-action="sync">${getQueue().length} pending · Retry sync</button>`:S.online?'Connected':'Offline mode'}<span class="release">v2.0</span></div>`}
function header(title='BodySmith',{back=false,finish=false}={}){const brand=title==='BodySmith'?`<div class="brand">Body<span>Smith</span></div><div class="tag">BUILD A STRONGER YOU</div>`:`<div class="brand">${esc(title)}</div>`;return `<header class="topbar"><button class="iconbtn" data-action="${back?'back':'noop'}">${back?'←':'BS'}</button><div class="grow">${brand}${S.user?cloudBadge():''}</div>${finish?'<button class="iconbtn" data-action="finish">Finish</button>':S.user?`<button class="avatar" data-nav="profile">${initials(S.user.display_name)}</button>`:'<span></span>'}</header>`}
function nav(){const items=[['plan','☷'],['exercises','🏋'],['workout','▰'],['supplements','◷'],['progress','▥'],['profile','◎']];return `<nav class="bottom-nav">${items.map(([n,i])=>`<button data-nav="${n}" class="${S.screen===n?'active':''}"><span>${i}</span><small>${n[0].toUpperCase()+n.slice(1)}</small></button>`).join('')}</nav>`}

function authView(){const reg=S.authMode==='register';return `<div class="auth-shell"><section class="auth-card"><div class="brand">Body<span>Smith</span></div><div class="tag">BUILD A STRONGER YOU</div><h1>${reg?'Create your account':'Welcome back'}</h1><p class="muted">${reg?'Your workouts and history will be private to your account.':'Sign in to sync workouts across your devices.'}</p><div class="auth-switch"><button data-authmode="login" class="${!reg?'active':''}">Sign in</button><button data-authmode="register" class="${reg?'active':''}">Create account</button></div>${S.authError?`<div class="form-error">${esc(S.authError)}</div>`:''}<form id="authForm">${reg?`<label class="field">Display name<input name="displayName" autocomplete="name" maxlength="50" placeholder="Your name" required/></label>`:''}<label class="field">Username<input name="username" autocapitalize="none" autocomplete="username" placeholder="Choose a username" required/></label><label class="field">Password<input name="password" type="password" autocomplete="${reg?'new-password':'current-password'}" minlength="6" required/></label><button class="primary huge" type="submit" ${S.busy?'disabled':''}>${S.busy?'Working…':reg?'Create BodySmith account':'Sign in'}</button></form><p class="tiny muted" style="margin-top:16px">Cloud accounts use a username and password. Passwords are hashed server-side and are never stored in the app.</p></section></div>`}

function shell(content,screen=S.screen){return `<div class="screen">${header('BodySmith')}${!S.online?'<div class="sync-banner">You are offline. Saved cloud data is available; new set entries will sync when the connection returns.</div>':''}${content}${nav()}</div>`}
function exerciseRow(slot){const e=slot.exercise;const prev=previousSets(e.id);const best=prev.find(x=>x.weight!=null);const sub=slot.duration_minutes?`${slot.duration_minutes} min • ${slot.target_rpe||'Easy'}`:`${slot.target_sets} sets × ${slot.min_reps}–${slot.max_reps} reps`;return `<button class="exercise-row" data-ex="${e.id}">${art(e)}<div class="exercise-copy"><strong>${esc(e.name)}</strong><span>${esc(sub)}</span>${best?`<span>Last: ${best.weight||0} ${S.user.units} × ${best.reps||0}</span>`:''}</div><div class="muscle">${esc(e.primary_muscle||'')}</div><span class="chev">›</span></button>`}
function home(){const d=selectedDay(),slots=dayExercises(d);if(!d)return shell(`<div class="empty">No workout plan found.</div>`);const active=S.active&&S.active.status==='in_progress';return shell(`<section class="card plan-banner"><div class="bolt">⚡</div><div><span class="muted tiny">Active Plan</span><h2 style="margin:2px 0">${esc(S.plan.name)}</h2><p class="muted tiny" style="margin:0">${esc(S.plan.goal||'Build strength')} • ${S.plan.days_per_week} days/week</p></div><span class="pill">${S.plan.days_per_week}-day split</span></section><div class="section-title"><h1>${active?'Resume workout':'Your next workout'}</h1><span class="muted">${active?'In progress':'Today'}</span></div><div class="day-tabs">${days().map(x=>`<button data-day="${x.id}" class="${x.id===d.id?'active':''}">${esc(x.name)}</button>`).join('')}</div><section class="card"><div class="workout-head"><div><h2>${esc(d.name)}</h2><p class="muted">${esc(d.focus||'')}</p></div><span class="pill">${slots.length} exercises</span></div>${slots.map(s=>exerciseRow(s)).join('')}<button class="primary huge" data-action="${active&&S.active.plan_day_id===d.id?'resume':'start'}" data-day="${d.id}">${active&&S.active.plan_day_id===d.id?'Resume Workout':'Start Workout'}</button></section>`,'workout')}
function planView(){return shell(`${planControls()}<div class="section-title"><h1>Training Plan</h1><span class="muted">${S.plan.days_per_week} days/week</span></div><section class="card plan-banner"><div class="bolt">⚡</div><div><h2 style="margin:0">${esc(S.plan.name)}</h2><p class="muted" style="margin:4px 0 0">${esc(S.plan.goal||'')}</p></div></section>${days().map(d=>`<details class="panel day-card" ${d.id===selectedDay()?.id?'open':''}><summary><div><strong>${esc(d.name)}</strong><div class="muted tiny">${esc(d.focus||'')}</div></div><span class="pill">${dayExercises(d).length} exercises</span></summary><div class="day-exercises">${dayExercises(d).map(s=>`<div class="mini-row"><div><strong>${esc(s.exercise.name)}</strong><div class="muted tiny">${s.duration_minutes?`${s.duration_minutes} min`:`${s.target_sets} × ${s.min_reps}–${s.max_reps}`} • RPE ${esc(s.target_rpe||'—')} • Rest ${s.rest_seconds||0}s</div></div><button class="secondary" data-ex="${s.exercise.id}">View</button></div>`).join('')}<button class="primary huge" data-action="start" data-day="${d.id}">Start ${esc(d.name)}</button></div></details>`).join('')}`,'plan')}
function exercisesView(){const q=S.search.trim().toLowerCase();const list=allExercises().filter(e=>!q||e.name.toLowerCase().includes(q)||(e.primary_muscle||'').toLowerCase().includes(q)||(e.equipment||'').toLowerCase().includes(q));return shell(`<div class="section-title"><h1>Exercises</h1><span class="muted">${allExercises().length} movements</span></div><div class="search"><input id="searchExercises" placeholder="Search exercise, muscle, equipment" value="${esc(S.search)}"/></div><div class="row-actions"><button class="secondary" data-extra="customexercise">Add custom exercise</button><button class="secondary" data-extra="favorites">${S.favoritesOnly?'Show all':'Favorites'}</button></div><section class="card">${list.filter(e=>!S.favoritesOnly||(S.user.preferences?.favorites||[]).includes(e.id)).map(e=>`<button class="exercise-row" data-ex="${e.id}">${art(e)}<div class="exercise-copy"><strong>${esc(e.name)}</strong><span>${esc(e.equipment||'Gym')} • ${esc(e.movement_type||'Movement')}</span></div><div class="muscle">${esc(e.primary_muscle||'')}</div><span class="chev">›</span></button>`).join('')||'<div class="empty">No exercises match that search.</div>'}</section>`,'exercises')}
function detailView(){const e=S.detail;const slots=[];for(const d of days())for(const s of dayExercises(d))if(s.exercise.id===e.id)slots.push({day:d,slot:s});const slot=slots[0]?.slot;const prev=previousSets(e.id);const weights=prev.map(x=>Number(x.weight)||0).filter(Boolean);const max=weights.length?Math.max(...weights):0;return `<div class="screen">${header(e.name,{back:true})}${movementDemo(e)}<button class="secondary" data-favorite="${e.id}">${(S.user.preferences?.favorites||[]).includes(e.id)?'★ Favorited':'☆ Add favorite'}</button><div class="chips"><span>${esc(e.primary_muscle||'')}</span><span>${esc(e.equipment||'Gym')}</span><span>${esc(e.movement_type||'Movement')}</span></div><section class="panel coach-cue"><b>Coach cue</b><p style="margin:6px 0 0">${esc(e.cue||'Move with control and use pain-free form.')}</p></section>${slot?`<div class="stats-grid"><div class="stat"><span>Sets</span><strong>${slot.target_sets}</strong></div><div class="stat"><span>Rep target</span><strong>${slot.duration_minutes?`${slot.duration_minutes}m`:`${slot.min_reps}–${slot.max_reps}`}</strong></div><div class="stat"><span>RPE</span><strong>${esc(slot.target_rpe||'—')}</strong></div><div class="stat"><span>Rest</span><strong>${slot.rest_seconds||0}s</strong></div></div>`:''}<section class="panel"><h3>Progression</h3><p>${esc(slot?.progression_rule||'Add reps before load while form remains clean.')}</p>${slot?.pain_rule?`<div class="pain">${esc(slot.pain_rule)}</div>`:''}</section><section class="panel"><h3>Recent performance</h3>${prev.length?`<div class="stats-grid"><div class="stat"><span>Best load</span><strong>${max} ${S.user.units}</strong></div><div class="stat"><span>Sets last time</span><strong>${prev.length}</strong></div></div>${prev.map(x=>`<div class="mini-row"><span>Set ${x.set_number}</span><strong>${x.weight??'—'} ${S.user.units} × ${x.reps??'—'} <span class="muted">RPE ${x.rpe??'—'}</span></strong></div>`).join('')}`:'<div class="empty">Log this exercise to start building your history.</div>'}</section>${(S.active?[]:slots).map(({day})=>`<button class="primary huge" data-action="start" data-day="${day.id}">Start ${esc(day.name)}</button>`).join('')}</div>`}

function activeView(){const day=S.activeDay,slots=dayExercises(day),slot=slots[S.activeIndex]||slots[0];if(!slot)return home();const ex=slot.exercise,logs=setsFor(ex.id),cur=Math.min(logs.length+1,slot.target_sets),prev=previousSets(ex.id),p=activeProgress();const last=prev[Math.min(logs.length,Math.max(0,prev.length-1))]||{};const alternates=substitutes(ex);return `<div class="screen">${header(day.name,{finish:true})}<div class="session-strip"><span>${p.logged}/${p.planned} sets logged</span><span>${p.pct}% complete</span></div><div class="progress"><div style="width:${p.pct}%"></div></div>${S.rest>0?`<div class="rest-card"><span>Rest timer</span><strong>${fmtTime(S.rest)}</strong><button data-action="skiprest">Skip</button></div>`:''}<button class="demo-open" data-ex="${ex.id}">${art(ex,true)}<span>Tap for movement demonstration</span></button><div class="active-title"><div><h1>${esc(ex.name)}</h1><p class="muted" style="margin:5px 0">${slot.duration_minutes?'Timed exercise':`${slot.rest_seconds||0} sec rest`} · ${/dumbbell/i.test(ex.equipment||'')?'Weight per dumbbell':'Load as shown on equipment'}</p></div><span class="setcount">Set ${cur}/${slot.target_sets}</span></div><div class="chips"><span>${slot.target_sets} sets</span>${slot.duration_minutes?`<span>${slot.duration_minutes} min</span>`:`<span>${slot.min_reps}–${slot.max_reps} reps</span>`}<span>RPE ${esc(slot.target_rpe||'—')}</span><span>${esc(ex.primary_muscle||'')}</span></div><section class="panel coach-cue"><b>Coach cue</b><p style="margin:6px 0 0">${esc(ex.cue||'Move with control.')}</p></section><div id="painBox"></div><div class="set-table"><div class="set-head"><span>Set</span><span>Last</span><span>${slot.duration_minutes?'Minutes':'Reps'}</span><span>${slot.duration_minutes?'Status':S.user.units}</span></div>${Array.from({length:slot.target_sets}).map((_,i)=>{const l=logs.find(x=>x.set_number===i+1),pv=prev.find(x=>x.set_number===i+1),current=!l&&i===logs.length;return `<div class="set-line ${current?'current':''}"><b>${i+1}</b><span>${pv?slot.duration_minutes?`${pv.duration_seconds?pv.duration_seconds/60:pv.reps||slot.duration_minutes} min`:`${pv.weight??'—'} × ${pv.reps??'—'}`:'—'}</span><span>${l?l.completion_status==='skipped'?'Skipped':slot.duration_minutes?(l.duration_seconds?l.duration_seconds/60:l.reps??'—'):l.reps??'—':current?`<input id="reps" aria-label="Actual reps or minutes" inputmode="decimal" value="${slot.duration_minutes?slot.duration_minutes:(last.reps||slot.min_reps||'')}"/>`:'—'}</span><span>${l?l.completion_status==='skipped'?'—':slot.duration_minutes?'Done':l.weight??'—':current?slot.duration_minutes?'<span class="muted">Cardio</span>':`<input id="weight" aria-label="Weight" inputmode="decimal" value="${last.weight??''}"/>`:'—'}</span></div>`}).join('')}</div>${logs.length<slot.target_sets?`<div class="quick-grid"><label class="field">RPE<input id="rpe" inputmode="decimal" value="${slot.duration_minutes?'':(last.rpe||7.5)}" placeholder="1–10"/></label><label class="field">Elbow pain<input id="painInput" inputmode="numeric" value="0" min="0" max="10"/></label></div><label class="field">Set note<input id="setNote" maxlength="200" placeholder="Optional note"/></label><button class="primary huge" data-action="logset">✓ Log Set</button>`:`<div class="coach-note">Exercise complete.</div>`}<div class="row-actions"><button class="secondary" data-action="prevexercise">← Previous</button><button class="secondary" data-action="nextexercise">Next →</button></div><div class="row-actions"><button class="secondary" data-action="toggleswap">Swap exercise</button><button class="dangerbtn" data-action="skipexercise">Skip exercise</button></div><section class="panel swap-panel ${S.swapOpen?'show':''}"><h3>Swap ${esc(ex.name)}</h3><p class="muted tiny">Choose another ${esc(ex.primary_muscle||'')} movement for this slot.</p><div class="swap-options">${alternates.map(a=>`<button data-swap="${a.id}"><span>${esc(a.name)}</span><span class="muted">${esc(a.equipment||'')}</span></button>`).join('')||'<div class="muted">No matching alternatives in this plan.</div>'}</div></section></div>`}
function summaryView(){const session=S.active,day=S.activeDay,sets=(session?.sets||[]).filter(x=>x.completion_status==='completed'),score=workoutScore(session,day),planned=dayExercises(day).reduce((n,s)=>n+s.target_sets,0),pct=planned?Math.round((session?.sets||[]).length/planned*100):0,avg=sets.length?(sets.reduce((n,x)=>n+(Number(x.rpe)||0),0)/sets.length).toFixed(1):'—',pain=sets.length?(sets.reduce((n,x)=>n+(Number(x.elbow_pain)||0),0)/sets.length).toFixed(1):'0',duration=Math.round((Date.now()-new Date(session.started_at).getTime())/1000);return `<div class="screen">${header('BodySmith')}<div class="section-title"><div><h1>Workout Summary</h1><p class="muted" style="margin:4px 0">${esc(day.name)} · Review before saving</p></div></div><section class="card summary-hero"><div class="ring" style="--pct:${Math.min(100,pct)*3.6}deg"><strong>${Math.min(100,pct)}%</strong><span>COMPLETE</span></div><div><span class="muted">BodySmith Score</span><h1 style="font-size:45px;margin:3px 0">${score}</h1><span style="color:var(--good)">▲ Session score</span></div></section><div class="stats-grid"><div class="stat"><span>Duration</span><strong>${fmtDur(duration)}</strong></div><div class="stat"><span>Sets logged</span><strong>${sets.length}</strong></div><div class="stat"><span>Avg RPE</span><strong>${avg}</strong></div><div class="stat"><span>Avg pain</span><strong>${pain}/10</strong></div></div><section class="panel"><h3>Session metrics</h3>${sessionComparison(session)}${sessionDetails(session)}</section><section class="panel"><h3>Completed exercises</h3>${dayExercises(day).map(s=>{const xs=(session.sets||[]).filter(x=>x.exercise_id===s.exercise.id),ok=xs.filter(x=>x.completion_status==='completed').length>=s.target_sets;return `<div class="summary-row">${art(s.exercise)}<div><strong>${esc(s.exercise.name)}</strong><div class="muted tiny">${xs.filter(x=>x.completion_status==='completed').length}/${s.target_sets} sets logged</div></div><span class="${ok?'check':'muted'}">${ok?'✓':'•'}</span></div>`}).join('')}</section><section class="panel"><h3>Coach notes</h3>${coachNotes(session,day).map(n=>`<div class="coach-note">${esc(n)}</div>`).join('')}</section><button class="secondary huge" data-action="resume">← Return to workout</button><button class="primary huge" data-action="complete">✓ Save & Finish</button></div>`}
function coachNotes(session,day){const notes=[];const sets=(session?.sets||[]).filter(x=>x.completion_status==='completed');const maxPain=sets.reduce((m,x)=>Math.max(m,Number(x.elbow_pain)||0),0);if(maxPain>=6)notes.push('One movement reached 6+/10 elbow pain. Stop or swap that movement next time and keep the replacement pain-free.');else if(maxPain>=4)notes.push('Elbow pain entered the caution range. Reduce load or arm volume if it returns next session.');for(const slot of dayExercises(day)){const xs=sets.filter(x=>x.exercise_id===slot.exercise.id);if(!slot.duration_minutes&&xs.length>=slot.target_sets&&xs.every(x=>(Number(x.reps)||0)>=slot.max_reps&&(Number(x.rpe)||10)<=rpeUpper(slot.target_rpe))){notes.push(`${slot.exercise.name}: you reached the top of the rep range at target effort. Consider a small load increase next time.`);break}}if(!notes.length)notes.push('Solid session. Keep adding reps within the target ranges before increasing load.');return notes}
function progressView(){const completed=S.history.filter(x=>x.status==='completed');const cutoff=Date.now()-30*86400000;const recent=completed.filter(x=>new Date(x.started_at).getTime()>=cutoff);const sets=recent.flatMap(x=>x.sets||[]).filter(x=>x.completion_status==='completed');const avgRpe=sets.length?(sets.reduce((n,x)=>n+(Number(x.rpe)||0),0)/sets.length).toFixed(1):'—';const avgPain=sets.length?(sets.reduce((n,x)=>n+(Number(x.elbow_pain)||0),0)/sets.length).toFixed(1):'—';const bestMap={};for(const h of completed)for(const x of h.sets||[]){if(x.completion_status!=='completed'||x.weight==null)continue;bestMap[x.exercise_id]=Math.max(bestMap[x.exercise_id]||0,Number(x.weight)||0)}const top=Object.entries(bestMap).map(([id,w])=>({e:allExercises().find(e=>e.id===id),w})).filter(x=>x.e).sort((a,b)=>b.w-a.w).slice(0,7);const maxTop=Math.max(1,...top.map(x=>x.w));return shell(`<div class="section-title"><h1>Progress</h1><span class="muted">Last 30 days</span></div><div class="stats-grid"><div class="stat"><span>Workouts</span><strong>${recent.length}</strong></div><div class="stat"><span>Sets</span><strong>${sets.length}</strong></div><div class="stat"><span>Avg RPE</span><strong>${avgRpe}</strong></div><div class="stat"><span>Avg pain</span><strong>${avgPain}</strong></div></div><section class="panel">${progressMetrics()}<h3>Strength markers</h3>${top.length?`<div class="bar-list">${top.map(x=>`<div class="bar-row"><span class="tiny">${esc(x.e.name)}</span><div class="bar"><i style="width:${Math.round(x.w/maxTop*100)}%"></i></div><strong>${x.w}</strong></div>`).join('')}</div>`:'<div class="empty">Complete workouts to build your progress chart.</div>'}</section><section class="panel"><h3>Workout history</h3>${completed.slice(0,12).map(historyRow).join('')||'<div class="empty">No completed workouts yet.</div>'}</section>`,'progress')}
function historyRow(h){const day=h.day_snapshot||dayById(h.plan_day_id)||h.day||{},sets=(h.sets||[]).filter(x=>x.completion_status==='completed');const avg=sets.length?(sets.reduce((n,x)=>n+(Number(x.rpe)||0),0)/sets.length).toFixed(1):'—';return `<details class="history-detail"><summary><div class="history-card"><div><strong>${esc(day.name||'Workout')}</strong><div class="meta">${new Date(h.started_at).toLocaleDateString()} • ${sets.length} sets • Avg RPE ${avg}</div></div><span class="pill">${h.duration_seconds?fmtDur(h.duration_seconds):'Saved'}</span></div></summary>${sessionDetails(h)}</details>`}
function profileView(){return shell(`${notificationPanel()}<button class="secondary huge" data-extra="editprofile">Training preferences & schedule</button>${checkinHistory()}<div class="section-title"><h1>Profile</h1><span class="muted">Cloud account</span></div><section class="card"><div class="profile-head"><div class="profile-avatar">${initials(S.user.display_name)}</div><div><h2 style="margin:0">${esc(S.user.display_name)}</h2><p class="muted" style="margin:4px 0">@${esc(S.user.username)}</p></div></div><label class="field">Display name<input id="displayName" value="${esc(S.user.display_name)}" maxlength="50"/></label><div class="field"><span>Units</span><div class="segmented"><button data-units="lb" class="${S.user.units==='lb'?'active':''}">Pounds (lb)</button><button data-units="kg" class="${S.user.units==='kg'?'active':''}">Kilograms (kg)</button></div></div><button class="primary huge" data-action="saveprofile">Save profile</button></section><section class="panel"><h3>Daily check-in</h3><div class="quick-grid"><label class="field">Body weight<input id="checkWeight" inputmode="decimal" placeholder="Optional"/></label><label class="field">Elbow pain<input id="checkPain" inputmode="numeric" placeholder="0–10"/></label></div><div class="quick-grid"><label class="field">Calories<input id="checkCalories" inputmode="numeric" placeholder="Optional"/></label><label class="field">Protein (g)<input id="checkProtein" inputmode="numeric" placeholder="Optional"/></label></div><label class="field">Steps<input id="checkSteps" inputmode="numeric" placeholder="Optional"/></label><label class="field">Notes<textarea id="checkNotes" placeholder="Recovery, sleep, soreness, anything useful"></textarea></label><button class="secondary huge" data-action="checkin">Save check-in</button></section><section class="panel"><h3>Account</h3><p class="muted">Your workout history is stored separately from every other BodySmith user.</p><button class="dangerbtn huge" data-action="logout">Sign out</button></section>`,'profile')}
function render(){if(!S.token||!S.user){app.innerHTML=authView();bind();return}if(!S.user.onboarding_completed){app.innerHTML=onboardingView();bind();bindExtras();return}if(S.editor){app.innerHTML=editorView();bind();bindExtras();return}if(S.screen==='supplements'){app.innerHTML=supplementsView();bind();bindExtras();return}if(S.detail){app.innerHTML=detailView();bind();return}if(S.screen==='active'&&S.active){app.innerHTML=activeView();bind();return}if(S.screen==='summary'&&S.active){app.innerHTML=summaryView();bind();return}if(S.screen==='plan')app.innerHTML=planView();else if(S.screen==='exercises')app.innerHTML=exercisesView();else if(S.screen==='progress')app.innerHTML=progressView();else if(S.screen==='profile')app.innerHTML=profileView();else app.innerHTML=home();bind()}

async function bootstrap(){scopeStorage();if(!S.token){render();return}S.busy=true;try{await syncQueue();const data=await api('bootstrap');S.user=data.user;scopeStorage();S.exercises=data.exercises||[];S.plans=data.plans||[];S.supplements=data.supplements||[];S.supplementLogs=data.supplementLogs||[];S.checkins=data.checkins||[];S.plan=data.plan;S.history=data.history||[];S.active=data.activeSession||null;if(S.active){S.activeDay=structuredClone(S.active.day_snapshot||dayById(S.active.plan_day_id));S.activeIndex=nextUnfinishedIndex(S.activeDay)}if(getQueue().length){const local=cache();if(local.user?.id===S.user.id){S.active=local.active||null;S.history=local.history||S.history;S.supplementLogs=local.supplementLogs||S.supplementLogs;if(S.active){S.activeDay=structuredClone(S.active.day_snapshot||dayById(S.active.plan_day_id));S.activeIndex=nextUnfinishedIndex(S.activeDay)}}}S.selectedDayId=nextDay()?.id||days()[0]?.id||null;setCache({user:S.user,plan:S.plan,history:S.history,active:S.active});await syncQueue();}catch(e){if(e.status===401){rememberPendingAccount();localStorage.removeItem(TOKEN_KEY);S.token='';S.user=null;S.authError='Your session expired. Sign in to the same account to restore and sync saved entries.'}else{const c=cache();if(c.user&&c.plan){S.user=c.user;S.exercises=c.exercises||[];S.plans=c.plans||[];S.supplements=c.supplements||[];S.supplementLogs=c.supplementLogs||[];S.checkins=c.checkins||[];S.plan=c.plan;S.history=c.history||[];S.active=c.active||null;S.online=false;if(S.active){S.activeDay=structuredClone(S.active.day_snapshot||dayById(S.active.plan_day_id));S.activeIndex=nextUnfinishedIndex(S.activeDay)}toast('Using saved offline data');}else{S.authError='Could not reach BodySmith. Check your connection and try again.'}}}finally{S.busy=false;render()}}
async function syncQueue(){if(!S.online||!S.token||S.syncing)return;S.syncing=true;try{let q=getQueue();while(q.length){const item=q[0];try{await api(item.action,item.payload,{timeout:10000})}catch(e){S.syncError=e.message;break}S.syncError='';q=getQueue();q.shift();setQueue(q)} }finally{S.syncing=false}}
function queue(action,payload){const q=getQueue();q.push({action,payload,at:Date.now()});setQueue(q)}
async function submitAuth(form){if(S.busy)return;S.authError='';S.busy=true;const fd=new FormData(form);try{const data=await api(S.authMode==='register'?'register':'login',{username:fd.get('username'),password:fd.get('password'),displayName:fd.get('displayName')||undefined});S.token=data.token;localStorage.setItem(TOKEN_KEY,S.token);S.user=data.user;restorePendingAccount();toast(S.authMode==='register'?'Account created':'Signed in');await bootstrap()}catch(e){S.authError=e.message||'Sign in failed';S.busy=false;render()}}
async function startWorkout(dayId){if(S.active){resumeWorkout();toast('Resumed your active workout. Finish it before starting another.');return}if(!S.online){toast('Connect to the internet to start a new cloud workout.',true);return}S.busy=true;try{const data=await api('start_session',{planDayId:dayId});S.active={...data.session,sets:data.session.sets||[]};S.activeDay=structuredClone(data.session.day_snapshot||dayById(dayId));S.activeIndex=0;S.screen='active';S.detail=null;setCache({user:S.user,plan:S.plan,history:S.history,active:S.active});render()}catch(e){toast(e.message,true)}finally{S.busy=false}}
function resumeWorkout(){if(!S.active)return;const until=Number(localStorage.getItem(CACHE_KEY+'-rest')||0);if(until>Date.now())setRest(Math.ceil((until-Date.now())/1000));S.activeDay=structuredClone(S.active.day_snapshot||dayById(S.active.plan_day_id));S.activeIndex=nextUnfinishedIndex(S.activeDay);S.screen='active';S.detail=null;render()}
function setRest(sec){clearInterval(S.restTimer);S.rest=Math.max(0,Number(sec)||0);S.restEnd=Date.now()+S.rest*1000;localStorage.setItem(CACHE_KEY+'-rest',String(S.restEnd));if(S.rest>0)S.restTimer=setInterval(()=>{S.rest=Math.max(0,Math.ceil((S.restEnd-Date.now())/1000));const el=document.querySelector('.rest-card strong');if(el)el.textContent=fmtTime(S.rest);if(!S.rest){clearInterval(S.restTimer);toast('Rest complete. Ready for your next set.');navigator.vibrate?.([150,90,150])}},1000)}
function persist(){if(S.active&&S.activeDay)S.active.day_snapshot=S.activeDay;setCache({user:S.user,plan:S.plan,history:S.history,active:S.active});}
function rememberPendingAccount(){const c=cache();if(!c.user?.id||!getQueue().length)return;let entries={};try{entries=JSON.parse(localStorage.getItem('bodysmith-recovery-v3')||'{}')}catch{}entries[c.user.id]={cacheKey:CACHE_KEY,queueKey:QUEUE_KEY};localStorage.setItem('bodysmith-recovery-v3',JSON.stringify(entries));}
function restorePendingAccount(){let entries={};try{entries=JSON.parse(localStorage.getItem('bodysmith-recovery-v3')||'{}')}catch{}const old=entries[S.user.id];scopeStorage();if(old){const c=localStorage.getItem(old.cacheKey),q=localStorage.getItem(old.queueKey);if(c&&q&&JSON.parse(c).user?.id===S.user.id){localStorage.setItem(CACHE_KEY,c);localStorage.setItem(QUEUE_KEY,q)}delete entries[S.user.id];localStorage.setItem('bodysmith-recovery-v3',JSON.stringify(entries));}}

function scopeStorage(){CACHE_KEY='bodysmith-cache-v3-'+S.token.slice(-24);QUEUE_KEY='bodysmith-queue-v3-'+S.token.slice(-24);const old=JSON.parse(localStorage.getItem('bodysmith-cache-v2')||'null');if(old&&S.token&&!localStorage.getItem(CACHE_KEY)){localStorage.setItem(CACHE_KEY,JSON.stringify(old));const q=localStorage.getItem('bodysmith-queue-v2');if(q)localStorage.setItem(QUEUE_KEY,q);localStorage.removeItem('bodysmith-cache-v2');localStorage.removeItem('bodysmith-queue-v2')}}
async function logSet(){
 if(S.saveBusy)return;const slot=dayExercises(S.activeDay)[S.activeIndex],ex=slot.exercise,existing=setsFor(ex.id);if(existing.length>=slot.target_sets)return;
 const value=id=>document.getElementById(id)?.value??'';const reps=value('reps'),weight=value('weight'),rpe=value('rpe'),pain=value('painInput');
 if(!reps||!Number.isFinite(+reps)||+reps<=0||(!slot.duration_minutes&&!Number.isInteger(+reps))||(+weight<0)||!Number.isFinite(+weight)||(rpe!==''&&(!Number.isFinite(+rpe)||+rpe<1||+rpe>10))||!Number.isFinite(+pain)||+pain<0||+pain>10){toast('Check reps/time, weight, RPE (1–10), and pain (0–10).',true);return}
 const payload={sessionId:S.active.id,exerciseId:ex.id,units:S.user.units,setNumber:existing.length+1,reps:slot.duration_minutes?null:+reps,durationSeconds:slot.duration_minutes?Math.round(+reps*60):null,weight:weight===''?null:+weight,rpe:rpe===''?null:+rpe,elbowPain:+pain,notes:value('setNote'),completionStatus:'completed'};
 const local={id:crypto.randomUUID(),session_id:S.active.id,exercise_id:ex.id,set_number:payload.setNumber,reps:payload.reps,weight:payload.weight,rpe:payload.rpe,elbow_pain:payload.elbowPain,duration_seconds:payload.durationSeconds,units:S.user.units,notes:payload.notes,completion_status:'completed',logged_at:new Date().toISOString()};
 S.saveBusy=true;try{S.active.sets.push(local);queue('save_set',payload);persist();setRest(slot.rest_seconds||0);navigator.vibrate?.(50);const old=previousSets(ex.id);if(old.length&&+weight>Math.max(...S.history.filter(h=>h.status==='completed').flatMap(h=>(h.sets||[]).filter(x=>x.exercise_id===ex.id&&x.completion_status==='completed').map(x=>(+x.weight||0)*((x.units||'lb')===S.user.units?1:S.user.units==='kg'?1/2.2046226218:2.2046226218)))))toast('New load record for this exercise!');render();await syncQueue();}finally{S.saveBusy=false}
}
async function skipExercise(){if(S.saveBusy)return;S.saveBusy=true;try{const slot=dayExercises(S.activeDay)[S.activeIndex],ex=slot.exercise;for(let i=setsFor(ex.id).length+1;i<=slot.target_sets;i++){const payload={sessionId:S.active.id,exerciseId:ex.id,setNumber:i,completionStatus:'skipped',notes:'Skipped'};S.active.sets.push({id:crypto.randomUUID(),exercise_id:ex.id,set_number:i,completion_status:'skipped'});queue('save_set',payload)}persist();if(S.activeIndex<dayExercises(S.activeDay).length-1)S.activeIndex++;render();await syncQueue();}finally{S.saveBusy=false}}
function pattern(e){const n=e.name.toLowerCase();if(/pulldown/.test(n))return'vertical pull';if(/row/.test(n))return'horizontal pull';if(/shoulder press/.test(n))return'vertical push';if(/pressdown/.test(n))return'elbow extension';if(/leg curl/.test(n))return'knee flexion';if(/curl/.test(n))return'elbow flexion';if(/chest fly/.test(n))return'chest fly';if(/bench|incline.*press|push.up/.test(n))return'horizontal push';if(/lateral/.test(n))return'lateral raise';return e.movement_type+' '+e.primary_muscle}
function substitutes(ex){const occupied=new Set(dayExercises(S.activeDay).map(s=>s.exercise.id));return allExercises().filter(a=>!occupied.has(a.id)&&(pattern(a)===pattern(ex)||a.primary_muscle===ex.primary_muscle)).sort((a,b)=>(pattern(b)===pattern(ex))-(pattern(a)===pattern(ex))).slice(0,12)}
async function swapExercise(id){const alt=allExercises().find(e=>e.id===id),slot=dayExercises(S.activeDay)[S.activeIndex];if(!alt)return;if(setsFor(slot.exercise.id).length){toast('Substitute before logging sets for this exercise.',true);return}const base=S.activeDay.plan_day_exercises.find(x=>x.id===slot.id);base.exercises=alt;base.exercise_id=id;queue('swap_exercise',{sessionId:S.active.id,slotId:slot.id,exerciseId:id});S.swapOpen=false;persist();render();await syncQueue();toast('Substitution saved for this workout')}
function showSummary(){S.screen='summary';setRest(0);render()}
async function completeWorkout(){if(!S.active||S.saveBusy)return;S.saveBusy=true;try{const finished={...S.active,status:'completed',completed_at:new Date().toISOString(),duration_seconds:Math.round((Date.now()-new Date(S.active.started_at))/1000),day_snapshot:S.activeDay};queue('complete_session',{sessionId:S.active.id,completedAt:finished.completed_at});S.history=[finished,...S.history.filter(h=>h.id!==finished.id)];S.active=null;S.activeDay=null;S.screen='workout';persist();S.selectedDayId=nextDay()?.id;render();await syncQueue();toast(getQueue().length?'Workout saved on device; sync pending.':'Workout saved to cloud');}finally{S.saveBusy=false}}
async function saveProfile(){const displayName=document.querySelector('#displayName')?.value?.trim();try{const data=await api('update_profile',{displayName,units:S.user.units});S.user=data.user;setCache({user:S.user,plan:S.plan,history:S.history,active:S.active});render();toast('Profile saved')}catch(e){toast(e.message,true)}}
async function saveCheckin(){try{await api('daily_checkin',{date:localDate(),weight:document.querySelector('#checkWeight')?.value,elbowPain:document.querySelector('#checkPain')?.value,calories:document.querySelector('#checkCalories')?.value,protein:document.querySelector('#checkProtein')?.value,steps:document.querySelector('#checkSteps')?.value,notes:document.querySelector('#checkNotes')?.value});await bootstrap();toast('Daily check-in saved')}catch(e){toast(e.message,true)}}
async function logout(){if(S.active||getQueue().length){toast('Finish your workout and sync pending entries before signing out.',true);return}try{const reg=await navigator.serviceWorker?.ready;const sub=await reg?.pushManager?.getSubscription();if(sub){await api('unsubscribe_push',{endpoint:sub.endpoint});await sub.unsubscribe()}}catch{}try{if(S.online)await api('logout')}catch{}localStorage.removeItem(TOKEN_KEY);localStorage.removeItem(CACHE_KEY);localStorage.removeItem(QUEUE_KEY);S.token='';S.user=null;S.plan=null;S.history=[];S.active=null;S.screen='workout';render()}
function painFeedback(){const n=Number(document.querySelector('#painInput')?.value||0),box=document.querySelector('#painBox');if(!box)return;box.innerHTML=n>=6?'<div class="pain danger">6+/10: stop or swap this movement. Do not push through sharp or escalating pain.</div>':n>=4?'<div class="pain">4–5/10: reduce load or volume and use a pain-free variation.</div>':''}

function bind(){
  bindExtras();
  const authForm=document.querySelector('#authForm');if(authForm)authForm.onsubmit=e=>{e.preventDefault();submitAuth(authForm)};
  document.querySelectorAll('[data-authmode]').forEach(b=>b.onclick=()=>{S.authMode=b.dataset.authmode;S.authError='';render()});
  document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{S.screen=b.dataset.nav;S.detail=null;render()});
  document.querySelectorAll('[data-day]').forEach(b=>{if(!b.dataset.action)b.onclick=()=>{S.selectedDayId=b.dataset.day;render()}});
  document.querySelectorAll('[data-ex]').forEach(b=>b.onclick=()=>{S.detail=allExercises().find(e=>e.id===b.dataset.ex)||null;render()});
  document.querySelectorAll('[data-swap]').forEach(b=>b.onclick=()=>swapExercise(b.dataset.swap));
  const search=document.querySelector('#searchExercises');if(search)search.oninput=e=>{S.search=e.target.value;const pos=e.target.selectionStart;render();const n=document.querySelector('#searchExercises');n?.focus();n?.setSelectionRange(pos,pos)};
  const pain=document.querySelector('#painInput');if(pain)pain.oninput=painFeedback;
  document.querySelectorAll('[data-units]').forEach(b=>b.onclick=()=>{S.user.units=b.dataset.units;render()});
  document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{const a=b.dataset.action;if(a==='noop')return;if(a==='sync'){await syncQueue();render();toast(getQueue().length?'Still pending. Your entries are saved on this device.':'All entries synced');return;}if(a==='back'){S.detail=null;render()}else if(a==='start')await startWorkout(b.dataset.day||S.selectedDayId||selectedDay()?.id);else if(a==='resume')resumeWorkout();else if(a==='logset')await logSet();else if(a==='skiprest'){setRest(0);render()}else if(a==='prevexercise'){S.activeIndex=Math.max(0,S.activeIndex-1);S.swapOpen=false;render()}else if(a==='nextexercise'){S.activeIndex=Math.min(dayExercises(S.activeDay).length-1,S.activeIndex+1);S.swapOpen=false;render()}else if(a==='skipexercise')await skipExercise();else if(a==='toggleswap'){S.swapOpen=!S.swapOpen;render()}else if(a==='finish')showSummary();else if(a==='complete')await completeWorkout();else if(a==='saveprofile')await saveProfile();else if(a==='checkin')await saveCheckin();else if(a==='logout')await logout()});
}

window.addEventListener('online',async()=>{S.online=true;toast('Back online');await syncQueue();if(S.token&&!S.active)bootstrap()});
window.addEventListener('offline',()=>{S.online=false;toast('Offline. Your workout remains saved on this device.');});
window.addEventListener('beforeunload',e=>{if(S.active||getQueue().length){e.preventDefault();e.returnValue=''}});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(async reg=>{await reg.update();S.pushEnabled=!!(await reg.pushManager?.getSubscription());if(S.screen==='supplements')render()}).catch(()=>{}));
const weekdays=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
const localDate=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const input=(name,label,value='',type='text',attrs='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
const select=(name,label,options,value)=>`<label class="field">${label}<select name="${name}">${options.map(x=>`<option ${String(x)===String(value)?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;
function dayChecks(selected=[1,2,4,6],name='days'){return `<div class="weekday-checks">${weekdays.map((d,i)=>`<label><input type="checkbox" name="${name}" value="${i}" ${selected.includes(i)?'checked':''}>${d}</label>`).join('')}</div>`}
function onboardingView(){const p=S.user.preferences||{};return `<div class="screen">${header()}<h1>Your training, your way.</h1><p class="muted">Set up your own profile. Every field below belongs to your account.</p><form id="onboardForm" class="panel">${input('displayName','Display name',S.user.display_name,'text','required maxlength="50" minlength="2"')}${select('goal','Training goal',['Build muscle','Build strength','General fitness','Improve consistency'],p.goal||'Build muscle')}${select('experience','Experience',['Beginner','Intermediate','Experienced'],p.experience||'Beginner')}<div class="quick-grid">${select('daysPerWeek','Days per week',[1,2,3,4,5,6,7],p.daysPerWeek||4)}${select('duration','Workout duration (minutes)',[20,30,45,60,75,90],p.duration||60)}</div>${input('equipment','Available equipment',p.equipment||'Gym machines, cables, dumbbells','text','required')}${select('units','Weight units',['lb','kg'],S.user.units)}<p>Intended training days</p>${dayChecks(p.trainingDays)}<details><summary>Optional profile information</summary>${input('age','Age',p.age||'','number','min="13" max="110"')}${input('height','Height (include unit)',p.height||'')}${input('bodyWeight','Body weight (selected units)',p.bodyWeight||'','number','min="1" step="0.1"')}${input('limitations','Training preferences or limitations',p.limitations||'')}</details><button class="primary huge" type="submit">Save & choose a plan</button></form></div>`}
function planControls(){return `<section class="panel"><h2>Find your routine</h2><p class="muted">Michael Muscle Builder is the recommended four-day starter. Edits always create a private copy.</p><label class="field">Choose a plan<select id="planChoice">${S.plans.map(p=>`<option value="${p.id}" ${p.id===S.plan?.id?'selected':''}>${esc(p.name)}${p.is_template?' · Template':' · Yours'}</option>`).join('')}</select></label><div class="row-actions"><button class="primary" data-extra="selectplan">Use selected plan</button><button class="secondary" data-extra="editplan">Clone & edit current</button></div><button class="secondary huge" data-extra="newplan">Create a custom plan</button></section>`}
function editorView(){const p=S.editor;return `<div class="screen">${header()}<h1>Build your plan</h1><p class="muted">Save creates a personal revision. Your past workouts stay intact.</p>${input('planName','Plan name',p.name,'text','id="editPlanName" maxlength="100"')}<div class="editor-days">${p.plan_days.map((d,di)=>`<section class="panel"><div class="mini-row"><label class="field">Day ${di+1} name<input data-dayname="${di}" value="${esc(d.name)}"></label><button class="dangerbtn" data-remove-day="${di}" aria-label="Remove day ${di+1}">Remove day</button></div>${d.plan_day_exercises.map((s,si)=>`<details class="editor-slot" open><summary>${si+1}. ${esc(s.exercises.name)}</summary><div class="editor-fields">${[['target_sets','Sets'],['min_reps','Min reps'],['max_reps','Max reps'],['target_rpe','RPE'],['rest_seconds','Rest seconds'],['duration_minutes','Minutes (timed)']].map(([k,l])=>`<label class="field">${l}<input data-slotfield="${di}:${si}:${k}" value="${esc(s[k]??(k==='duration_minutes'?0:''))}" inputmode="${k==='target_rpe'?'text':'numeric'}"></label>`).join('')}</div><div class="slot-actions"><button class="secondary" data-move-slot="${di}:${si}:-1" ${si===0?'disabled':''} aria-label="Move ${esc(s.exercises.name)} up">↑</button><button class="secondary" data-move-slot="${di}:${si}:1" ${si===d.plan_day_exercises.length-1?'disabled':''} aria-label="Move ${esc(s.exercises.name)} down">↓</button><button class="dangerbtn" data-remove-slot="${di}:${si}">Remove exercise</button></div></details>`).join('')}<label class="field">Add exercise<select id="addExercise${di}">${allExercises().filter(e=>!d.plan_day_exercises.some(s=>s.exercises.id===e.id)).map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select></label><button class="secondary" data-add-exercise="${di}">Add exercise</button></section>`).join('')}</div><button class="secondary huge" data-extra="addday">Add training day</button><div class="row-actions"><button class="secondary" data-extra="canceledit">Cancel</button><button class="primary" data-extra="saveplan">Save personal plan</button></div></div>`}
function supplementForm(){const s=S.suppEditor||{};return `<form id="suppForm" class="panel"><h2>${s.id?'Edit':'Add'} supplement</h2><p class="muted">Enter the dose you use. BodySmith does not recommend doses.</p>${input('name','Supplement name',s.name||'','text','list="suppNames" required maxlength="100"')}<datalist id="suppNames">${['Creatine','Protein powder','Magnesium','Zinc','Multivitamin','Turmeric','Omega-3','Vitamin D'].map(n=>`<option value="${n}">`).join('')}</datalist><div class="quick-grid">${input('dose','Your dose',s.dose||'')}${input('unit','Unit (g, mg, capsules…)',s.unit||'')}</div>${input('times','Times (24-hour, separated by commas)',(s.times||['09:00']).join(', '),'text','required placeholder="09:00, 18:00"')}<p>Scheduled days</p>${dayChecks(s.schedule_days||[0,1,2,3,4,5,6],'suppDays')}${input('with_food','With food note (optional)',s.with_food||'')}${input('notes','Personal notes',s.notes||'')}<label class="check-label"><input type="checkbox" name="active" ${s.active!==false?'checked':''}> Active</label><label class="check-label"><input type="checkbox" name="reminders" ${s.reminders?'checked':''}> Remind me at scheduled times</label><div class="row-actions"><button class="secondary" type="button" data-extra="cancelsupp">Cancel</button><button class="primary" type="submit">Save supplement</button></div></form>`}
function todayDoses(){const date=localDate();return S.supplements.filter(s=>s.active&&s.schedule_days.includes(new Date().getDay())).flatMap(s=>s.times.map(time=>({s,time,log:S.supplementLogs.find(l=>l.supplement_id===s.id&&l.scheduled_date===date&&l.scheduled_time===time)}))).sort((a,b)=>a.time.localeCompare(b.time))}
function supplementsView(){const doses=todayDoses(),taken=doses.filter(d=>d.log?.status==='taken').length;return shell(`<div class="section-title"><h1>Supplements</h1><span>${taken}/${doses.length} taken today</span></div>${S.suppEditor?supplementForm():`<button class="primary huge" data-extra="addsupp">Add supplement</button>`}<section class="panel"><h2>Today's checklist</h2>${doses.map(({s,time,log})=>`<article class="dose"><div class="mini-row"><div><strong>${esc(s.name)}</strong><p class="muted">${esc(s.dose)} ${esc(s.unit)} · ${time}<br>${esc(s.with_food)}</p></div><span class="pill">${log?.status||'Due'}</span></div>${log?.status==='snoozed'?`<p class="muted">Snoozed until ${new Date(log.snoozed_until).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</p>`:''}<div class="dose-actions">${['taken','skipped','snoozed'].map(status=>`<button class="${status==='taken'?'primary':'secondary'}" data-dose="${s.id}|${time}|${status}">${status==='snoozed'?'Snooze 15m':status==='taken'?'Taken':'Skipped'}</button>`).join('')}</div></article>`).join('')||'<p class="muted">No supplements scheduled today.</p>'}</section><section class="panel"><h2>Your supplements</h2>${S.supplements.map(s=>`<div class="mini-row"><div><strong>${esc(s.name)}</strong><div class="muted">${s.active?'Active':'Inactive'} · ${s.times.join(', ')}</div></div><button class="secondary" data-editsupp="${s.id}">Edit</button></div>`).join('')||'<p class="muted">Add your first supplement above.</p>'}</section>${notificationPanel()}<section class="panel"><h2>Adherence history</h2><p class="muted">${S.supplementLogs.filter(l=>l.status==='taken').length} taken · ${S.supplementLogs.filter(l=>l.status==='skipped').length} skipped · last 90 days. Unlogged doses are not counted as taken.</p>${S.supplementLogs.slice().sort((a,b)=>(b.logged_at||'').localeCompare(a.logged_at||'')).slice(0,50).map(l=>`<div class="mini-row"><span>${esc(S.supplements.find(s=>s.id===l.supplement_id)?.name||'Supplement')}<br><small>${l.scheduled_date} ${l.scheduled_time}</small></span><strong>${l.status}</strong></div>`).join('')}</section>`)}
function notificationPanel(){const p=S.user.preferences||{},supported='Notification'in window&&'PushManager'in window&&'serviceWorker'in navigator,status=!supported?'Push unavailable in this browser. In-app reminders are available.':Notification.permission==='denied'?'Blocked in browser settings. In-app reminders remain available.':S.pushEnabled?'Push enabled on this device':Notification.permission==='granted'?'Permission granted; enable this device below.':'Not enabled. Choose when you want reminders.';return `<section class="panel"><h2>Reminders</h2><p class="muted" id="notificationStatus">${status}</p><label class="check-label"><input id="suppReminder" type="checkbox" ${p.supplementReminders?'checked':''}> Supplement reminders</label><label class="check-label"><input id="workoutReminder" type="checkbox" ${p.workoutReminders?'checked':''}> Planned workout days</label>${input('workoutTime','Workout reminder time',p.workoutTime||'17:00','time','id="workoutReminderTime"')}<p class="muted tiny">${esc(p.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone)} · In-app reminders appear while BodySmith is open.</p><div class="row-actions"><button class="secondary" data-extra="savereminders">Save preferences</button><button class="primary" data-extra="enablepush" ${!supported?'disabled':''}>${S.pushEnabled?'Disable device push':'Enable notifications'}</button></div></section>`}
async function updatePreferences(p){const d=await api('update_profile',{displayName:S.user.display_name,units:S.user.units,preferences:{...S.user.preferences,...p}});S.user=d.user;persist()}
function sessionComparison(h){const previous=S.history.find(p=>p.status==='completed'&&p.id!==h.id&&(p.plan_day_id===h.plan_day_id||(p.day_snapshot?.name&&p.day_snapshot.name===h.day_snapshot?.name)));if(!previous)return '<p class="muted">First workout for this day. This session becomes your comparison baseline.</p>';const volume=x=>(x.sets||[]).filter(s=>s.completion_status==='completed').reduce((v,s)=>v+(+s.weight||0)*(+s.reps||0)*(s.units==='kg'?2.2046226218:1),0),before=volume(previous),after=volume(h),delta=before?Math.round((after-before)/before*100):null;return `<p>Last ${esc(h.day_snapshot?.name||'matching workout')}: ${new Date(previous.started_at).toLocaleDateString()}${delta==null?'':` · Load volume ${delta>=0?'+':''}${delta}%`}</p><p class="muted tiny">Compare sessions with similar exercise selections. More volume is not always the goal.</p>`;}

function sessionDetails(h){const sets=(h.sets||[]).filter(x=>x.completion_status==='completed'),volume=sets.reduce((a,x)=>a+(+x.weight||0)*(+x.reps||0)*(x.units==='kg'?2.2046226218:1),0)/(S.user.units==='kg'?2.2046226218:1);return `<p><strong>${Math.round(volume).toLocaleString()} ${S.user.units}·reps</strong> logged load volume</p><p class="muted tiny">Sum of entered load × reps; per-dumbbell loads are not doubled.</p>${sets.map(x=>{const e=allExercises().find(e=>e.id===x.exercise_id),rm=+x.reps>=1&&+x.reps<=10&&+x.weight>0&&/press|squat|deadlift|row/i.test(e?.name||'')?(+x.weight*(1+(+x.reps)/30)).toFixed(1):null;return `<div class="mini-row"><span>${esc(e?.name||'Exercise')} · set ${x.set_number}<br><small class="muted">${esc(x.notes||'')}</small></span><span>${x.duration_seconds?fmtDur(x.duration_seconds):`${x.weight??0} ${x.units||'lb'} × ${x.reps??0}`}<br><small class="muted">RPE ${x.rpe??'—'}${rm?` · est. 1RM ${rm} ${x.units||'lb'}`:''}</small></span></div>`}).join('')}<p class="muted tiny">Estimated 1RM uses the Epley formula for 1–10 reps on strength movements. It is a trend estimate, not a tested maximum.</p>`}
function progressMetrics(){const hs=S.history.filter(h=>h.status==='completed');const dates=new Set(hs.map(h=>localDate(new Date(h.started_at))));let streak=0,d=new Date();if(!dates.has(localDate(d)))d.setDate(d.getDate()-1);while(dates.has(localDate(d))){streak++;d.setDate(d.getDate()-1)}const week=new Date();week.setDate(week.getDate()-((week.getDay()+6)%7));week.setHours(0,0,0,0);return `<div class="stats-grid"><div class="stat"><span>This week / planned</span><strong>${hs.filter(h=>new Date(h.started_at)>=week).length} / ${S.user.preferences?.daysPerWeek||S.plan.days_per_week}</strong></div><div class="stat"><span>Consecutive training days</span><strong>${streak}</strong></div></div><p class="muted tiny">Rest days are expected. The streak counts consecutive calendar days trained.</p>`}
function checkinHistory(){return `<details class="panel"><summary>Daily check-in history</summary>${S.checkins.map(c=>`<div class="mini-row"><span>${c.checkin_date}</span><span>${c.body_weight??'—'} · pain ${c.elbow_pain??'—'}<br>${esc(c.notes||'')}</span></div>`).join('')||'<p class="muted">No check-ins yet.</p>'}</details>`}
function newSlot(e){return{exercises:e,exercise_id:e.id,target_sets:3,min_reps:8,max_reps:12,target_rpe:'7–8',rest_seconds:90,duration_minutes:0}}
function bindExtras(){
 const on=(selector,fn)=>document.querySelectorAll(selector).forEach(el=>el.onclick=async ev=>{ev.preventDefault();if(el.disabled)return;el.disabled=true;try{await fn(el)}catch(e){toast(e.message||'Could not save. Please retry.',true)}finally{el.disabled=false}});
 const form=document.getElementById('onboardForm');if(form)form.onsubmit=async ev=>{ev.preventDefault();const fd=new FormData(form),days=fd.getAll('days').map(Number);if(!days.length){toast('Choose at least one training day.',true);return}try{const preferences={...S.user.preferences,...Object.fromEntries(fd),trainingDays:days,daysPerWeek:+fd.get('daysPerWeek'),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone};const r=await api('update_profile',{displayName:fd.get('displayName'),units:fd.get('units'),preferences,onboardingCompleted:true});S.user=r.user;S.screen='plan';persist();render()}catch(e){toast(e.message,true)}};
 const sf=document.getElementById('suppForm');if(sf)sf.onsubmit=async ev=>{ev.preventDefault();const fd=new FormData(sf);try{const r=await api('save_supplement',{supplement:{...S.suppEditor,...Object.fromEntries(fd),times:String(fd.get('times')).split(',').map(s=>s.trim()),schedule_days:fd.getAll('suppDays').map(Number),active:fd.has('active'),reminders:fd.has('reminders')}});S.supplements=[...S.supplements.filter(s=>s.id!==r.supplement.id),r.supplement];S.suppEditor=null;persist();render();toast('Supplement saved')}catch(e){toast(e.message,true)}};
 on('[data-extra]',async el=>{switch(el.dataset.extra){
 case 'editprofile':S.user.onboarding_completed=false;render();break;
 case 'selectplan':await api('select_plan',{planId:document.getElementById('planChoice').value});await bootstrap();toast('Plan selected');break;
 case 'editplan':if(S.active)throw Error('Finish your active workout before editing plans.');S.editor=structuredClone(S.plan);S.editor.name+=' — My copy';render();break;
 case 'newplan':if(S.active)throw Error('Finish your active workout before editing plans.');S.editor={name:'My training plan',goal:S.user.preferences?.goal||'Build strength',plan_days:[{name:'Day 1',plan_day_exercises:[]}]};render();break;
 case 'addday':if(S.editor.plan_days.length>=7)throw Error('Maximum seven training days.');S.editor.plan_days.push({name:`Day ${S.editor.plan_days.length+1}`,plan_day_exercises:[]});render();break;
 case 'canceledit':S.editor=null;render();break;
 case 'saveplan':{const r=await api('save_plan',{plan:S.editor});S.editor=null;S.plan=r.plan;await bootstrap();toast('Personal plan saved');break;}
 case 'addsupp':S.suppEditor={};render();break;
 case 'cancelsupp':S.suppEditor=null;render();break;
 case 'favorites':S.favoritesOnly=!S.favoritesOnly;render();break;
 case 'customexercise':S.customForm=true;app.insertAdjacentHTML('beforeend',`<dialog open class="custom-dialog"><form id="customForm"><h2>Custom exercise</h2>${input('name','Exercise name','','text','required')}${input('muscle','Muscle group','','text','required')}${input('movement','Movement pattern','','text','required')}${input('equipment','Equipment')}${input('cue','Your setup and movement instructions','','text','required')}<button class="primary huge">Save exercise</button><button type="button" class="secondary huge" id="cancelCustom">Cancel</button></form></dialog>`);document.getElementById('cancelCustom').onclick=()=>render();document.getElementById('customForm').onsubmit=async ev=>{ev.preventDefault();try{const r=await api('custom_exercise',Object.fromEntries(new FormData(ev.target)));S.exercises.push(r.exercise);persist();render();toast('Exercise created')}catch(e){toast(e.message,true)}};break;
 case 'savereminders':await updatePreferences({supplementReminders:document.getElementById('suppReminder').checked,workoutReminders:document.getElementById('workoutReminder').checked,workoutTime:document.getElementById('workoutReminderTime').value,timezone:Intl.DateTimeFormat().resolvedOptions().timeZone});toast('Reminder preferences saved');break;
 case 'enablepush':await togglePush();render();break;
 }});
 on('[data-editsupp]',el=>{S.suppEditor=structuredClone(S.supplements.find(s=>s.id===el.dataset.editsupp));render()});
 on('[data-dose]',async el=>{const [supplementId,time,status]=el.dataset.dose.split('|'),payload={supplementId,time,status,date:localDate()};const log={supplement_id:supplementId,scheduled_time:time,scheduled_date:payload.date,status,logged_at:new Date().toISOString(),snoozed_until:status==='snoozed'?new Date(Date.now()+900000).toISOString():null};S.supplementLogs=[...S.supplementLogs.filter(l=>!(l.supplement_id===supplementId&&l.scheduled_time===time&&l.scheduled_date===payload.date)),log];queue('log_supplement',payload);persist();render();await syncQueue();toast(getQueue().length?'Saved on device; sync pending.':'Supplement logged')});
 on('[data-favorite]',async el=>{const ids=new Set(S.user.preferences?.favorites||[]);ids.has(el.dataset.favorite)?ids.delete(el.dataset.favorite):ids.add(el.dataset.favorite);await updatePreferences({favorites:[...ids]});render()});
 const name=document.getElementById('editPlanName');if(name)name.oninput=()=>S.editor.name=name.value;
 document.querySelectorAll('[data-dayname]').forEach(el=>el.oninput=()=>S.editor.plan_days[+el.dataset.dayname].name=el.value);
 document.querySelectorAll('[data-slotfield]').forEach(el=>el.oninput=()=>{const [d,s,k]=el.dataset.slotfield.split(':');S.editor.plan_days[d].plan_day_exercises[s][k]=k==='target_rpe'?el.value:+el.value});
 on('[data-remove-day]',el=>{S.editor.plan_days.splice(+el.dataset.removeDay,1);render()});
 on('[data-add-exercise]',el=>{const di=+el.dataset.addExercise,id=document.getElementById('addExercise'+di).value,e=allExercises().find(e=>e.id===id);if(e)S.editor.plan_days[di].plan_day_exercises.push(newSlot(e));render()});
 on('[data-remove-slot]',el=>{const [d,s]=el.dataset.removeSlot.split(':').map(Number);S.editor.plan_days[d].plan_day_exercises.splice(s,1);render()});
 on('[data-move-slot]',el=>{const [d,s,delta]=el.dataset.moveSlot.split(':').map(Number),xs=S.editor.plan_days[d].plan_day_exercises;[xs[s],xs[s+delta]]=[xs[s+delta],xs[s]];render()});
 on('[data-demo-pause]',el=>{const box=document.querySelector('.movement-demo');box.classList.toggle('paused');el.textContent=box.classList.contains('paused')?'Play':'Pause'});
 on('[data-demo-speed]',el=>{const box=document.querySelector('.movement-demo');box.classList.toggle('slow');el.textContent=box.classList.contains('slow')?'Normal speed':'Slow speed'});
}
async function togglePush(){const reg=await navigator.serviceWorker.ready,old=await reg.pushManager.getSubscription();if(old){await api('unsubscribe_push',{endpoint:old.endpoint});await old.unsubscribe();S.pushEnabled=false;toast('Push disabled on this device');return}const config=await api('notification_config');if(!config.configured)throw Error('Push setup is not ready. In-app reminders are available.');const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('Notifications not enabled. In-app reminders remain available.');const raw=atob(config.publicKey.replace(/-/g,'+').replace(/_/g,'/')),key=Uint8Array.from(raw,c=>c.charCodeAt(0));const sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});try{await api('subscribe_push',{subscription:sub.toJSON()});S.pushEnabled=true;toast('Device notifications enabled')}catch(e){await sub.unsubscribe();throw e}}
let reminderShown=new Set();setInterval(()=>{if(!S.user)return;const p=S.user.preferences||{},now=new Date(),time=now.toTimeString().slice(0,5),key=localDate()+time;if(p.supplementReminders)for(const d of todayDoses()){const due=d.log?.status==='snoozed'?new Date(d.log.snoozed_until)<=now:!d.log&&d.time<=time,k=localDate()+d.s.id+d.time+(d.log?.snoozed_until||'');if(due&&d.s.reminders&&!reminderShown.has(k)){reminderShown.add(k);toast(`Supplement reminder: ${d.s.name}. Open Supplements to log it.`)}}if(p.workoutReminders&&p.trainingDays?.includes(now.getDay())&&p.workoutTime===time&&!reminderShown.has(key)){reminderShown.add(key);toast('Your planned workout is due. Ready when you are.')}},30000);

bootstrap();
